const updateDocument = `-- name: UpdateDocument :one
UPDATE documents SET
    title  = COALESCE($1::varchar(256), title),
    status = COALESCE($2::doc_status, status)
WHERE id = $3 AND deleted_at IS NULL
RETURNING id, group_id, title, status, default_role, latest_snapshot, latest_update_seq, word_count, created_by, created_at, updated_at, deleted_at
`

type UpdateDocumentParams struct {
	Title  *string       `json:"title"`
	Status NullDocStatus `json:"status"`
	ID     pgtype.UUID   `json:"id"`
}

// 局部更新：参数为 NULL 表示「本次不修改」。
// 只允许改标题与状态：default_role 决定群成员的默认文档权限，
// 经由 PATCH 修改会让 editor 悄悄把群成员降为 viewer，故不开放。
func (q *Queries) UpdateDocument(ctx context.Context, arg UpdateDocumentParams) (Document, error) {
	row := q.db.QueryRow(ctx, updateDocument, arg.Title, arg.Status, arg.ID)
	var i Document
	err := row.Scan(
		&i.ID,
		&i.GroupID,
		&i.Title,
		&i.Status,
		&i.DefaultRole,
		&i.LatestSnapshot,
		&i.LatestUpdateSeq,
		&i.WordCount,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}

const upsertDocMember = `-- name: UpsertDocMember :one
INSERT INTO doc_members (doc_id, user_id, role, granted_by)
VALUES ($1, $2, $3, $4)
ON CONFLICT (doc_id, user_id) DO UPDATE
SET role = EXCLUDED.role, granted_by = EXCLUDED.granted_by
RETURNING doc_id, user_id, role, granted_by, created_at
`

type UpsertDocMemberParams struct {
	DocID     pgtype.UUID `json:"doc_id"`
	UserID    pgtype.UUID `json:"user_id"`
	Role      DocRole     `json:"role"`
	GrantedBy pgtype.UUID `json:"granted_by"`
}

// 幂等授予/覆盖角色：同一用户重复设置只更新角色与授权人。
func (q *Queries) UpsertDocMember(ctx context.Context, arg UpsertDocMemberParams) (DocMember, error) {
	row := q.db.QueryRow(ctx, upsertDocMember,
		arg.DocID,
		arg.UserID,
		arg.Role,
		arg.GrantedBy,
	)
	var i DocMember
	err := row.Scan(
		&i.DocID,
		&i.UserID,
		&i.Role,
		&i.GrantedBy,
		&i.CreatedAt,
	)
	return i, err
}
